package org.sleepwell.app;
import android.content.*;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import androidx.test.platform.app.InstrumentationRegistry;import org.json.*;import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
/** Private SQLite/API boundaries only. Never obtains a real Health Connect client. */
public final class HealthSleepStorageTest {
 final Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();
 final class Fixture implements AutoCloseable {final String name="health-sleep-"+UUID.randomUUID()+".db";final Store store=new Store(c,name);final long now=System.currentTimeMillis(),start=now-86400000,end=start+8*3600000;final HealthSleepStore local=new HealthSleepStore(store);HealthSleep source(String id,long modified,String notes){return new HealthSleep(id,"com.provider.sleep",start,end,modified,7200,3600,"Reported sleep",notes,List.of(new HealthSleep.Stage(start,start+60000,1),new HealthSleep.Stage(start+60000,end,4)));}long imported(){return store.rows("SELECT id FROM sessions WHERE health_connect<>''").get(0).optLong("id");}public void close(){store.close();c.deleteDatabase(name);}}
 @Test public void importDedupUpdateAndReportedAwakePersistWithoutSensorOrAudioRows()throws Exception{try(Fixture f=new Fixture()){HealthSleep first=f.source("remote",1,"Original");f.local.apply(List.of(first),List.of(),"token-1","org.sleepwell.app",f.now);long id=f.imported();String before=BackupFingerprint.read(f.store);f.local.apply(List.of(first),List.of(),"token-1","org.sleepwell.app",f.now+1);assertEquals(before,BackupFingerprint.read(f.store));f.local.apply(List.of(f.source("remote",2,"Changed")),List.of(),"token-2","org.sleepwell.app",f.now+2);assertEquals(id,f.imported());assertEquals(1,Records.all(f.store).size());RecordEntry r=Records.get(f.store,id);assertTrue(r.provenance().startsWith("Health Connect import"));assertEquals(8*3600000-60000,r.duration());assertEquals("Changed",HealthSleepCodec.read(r.healthConnect).notes);assertEquals(r.healthConnect,r.draft(r.edit.copy()).healthConnect);for(String table:List.of("epochs","clips","sound_events","tracking_pauses"))assertTrue(f.store.rows("SELECT * FROM "+table).isEmpty());Backup.validate(f.store.backup());try(Store reopened=new Store(c,f.name)){assertEquals(r.healthConnect,Records.get(reopened,id).healthConnect);assertEquals("token-2",new HealthSleepStore(reopened).token());}}}
 @Test public void localEditsWaitForActualProviderChangeAndRequireFreshResolution()throws Exception{try(Fixture f=new Fixture()){HealthSleep first=f.source("remote",1,"Original");f.local.apply(List.of(first),List.of(),"a","org.sleepwell.app",f.now);long id=f.imported();RecordEntry r=Records.get(f.store,id);RecordDraft edit=r.edit.copy();edit.note="Local note";Records.save(f.store,id,edit,r.updated,f.now+1);f.local.apply(List.of(first),List.of(),"b","org.sleepwell.app",f.now+2);assertEquals(0,f.local.conflicts());HealthSleep next=f.source("remote",2,"Provider edit");f.local.apply(List.of(next),List.of(),"c","org.sleepwell.app",f.now+3);assertEquals(1,f.local.conflicts());assertEquals("Local note",Records.get(f.store,id).edit.note);JSONObject waiting=f.store.rows("SELECT * FROM health_imports").get(0);String fp=f.local.fingerprint(id),payload=waiting.getString("payload");r=Records.get(f.store,id);edit=r.edit.copy();edit.note="New local note";Records.save(f.store,id,edit,r.updated,f.now+4);String untouched=BackupFingerprint.read(f.store);assertThrows(IllegalStateException.class,()->f.local.resolve("remote",fp,payload,true,f.now+5));assertEquals(untouched,BackupFingerprint.read(f.store));f.local.resolve("remote",f.local.fingerprint(id),payload,true,f.now+6);assertEquals("Reported sleep\nProvider edit",Records.get(f.store,id).edit.note);assertEquals(0,f.local.conflicts());}}
 @Test public void keepLocalIsDurableAndLaterProviderChangesDoNotOverwrite()throws Exception{try(Fixture f=new Fixture()){f.local.apply(List.of(f.source("remote",1,"Original")),List.of(),"a","org.sleepwell.app",f.now);long id=f.imported();RecordEntry r=Records.get(f.store,id);RecordDraft draft=r.edit.copy();draft.note="Kept local";Records.save(f.store,id,draft,r.updated,f.now+1);f.local.apply(List.of(f.source("remote",2,"New")),List.of(),"b","org.sleepwell.app",f.now+2);String payload=f.store.rows("SELECT payload FROM health_imports").get(0).getString("payload");f.local.resolve("remote",f.local.fingerprint(id),payload,false,f.now+3);f.local.apply(List.of(f.source("remote",3,"Later")),List.of("remote"),"c","org.sleepwell.app",f.now+4);assertEquals("Kept local",Records.get(f.store,id).edit.note);assertEquals("kept",f.store.rows("SELECT status FROM health_imports").get(0).getString("status"));}}
 @Test public void remoteDeletionRemovesOnlyAnUneditedImportedCopy()throws Exception{try(Fixture f=new Fixture()){long local=Records.create(f.store,new RecordDraft(f.start-3600000,f.start-1000),java.time.ZoneId.of("UTC"),f.now);f.local.apply(List.of(f.source("remote",1,"")),List.of(),"a","org.sleepwell.app",f.now);long imported=f.imported();f.local.apply(List.of(),List.of("unknown","remote"),"b","org.sleepwell.app",f.now);assertFalse(f.local.exists(imported));assertNotNull(Records.get(f.store,local));assertEquals("deleted",f.store.rows("SELECT status FROM health_imports").get(0).getString("status"));}}
 @Test public void localDeleteHidesCopyAcrossProviderUpdateUntilExplicitReset()throws Exception{try(Fixture f=new Fixture()){f.local.apply(List.of(f.source("remote",1,"")),List.of(),"a","org.sleepwell.app",f.now);long id=f.imported();Records.delete(f.store,id,Records.get(f.store,id).updated);f.local.apply(List.of(f.source("remote",2,"Changed")),List.of(),"b","org.sleepwell.app",f.now);assertTrue(Records.all(f.store).isEmpty());assertEquals("hidden",f.store.rows("SELECT status FROM health_imports").get(0).getString("status"));f.local.allowHidden();assertEquals("",f.local.token());f.local.apply(List.of(f.source("remote",2,"Changed")),List.of(),"c","org.sleepwell.app",f.now);assertEquals(1,Records.all(f.store).size());}}
 @Test public void ownOriginAndFutureBatchCannotCreateFeedbackOrPartiallyAdvanceToken()throws Exception{try(Fixture f=new Fixture()){HealthSleep own=new HealthSleep("own","org.sleepwell.app",f.start,f.end,1,null,null,"","",List.of());f.local.apply(List.of(own),List.of(),"a","org.sleepwell.app",f.now);assertTrue(Records.all(f.store).isEmpty());String before=BackupFingerprint.read(f.store);HealthSleep future=new HealthSleep("future","com.provider.sleep",f.now,f.now+60000,1,null,null,"","",List.of());assertThrows(IllegalArgumentException.class,()->f.local.apply(List.of(f.source("valid",1,""),future),List.of(),"bad","org.sleepwell.app",f.now));assertEquals(before,BackupFingerprint.read(f.store));}}
 @Test public void portableSourceRoundTripNeverRestoresLivePermissionsOrSyncOwnership()throws Exception{try(Fixture f=new Fixture();Fixture target=new Fixture()){f.local.apply(List.of(f.source("remote",1,"Notes")),List.of(),"private-token","org.sleepwell.app",f.now);JSONObject backup=f.store.backup();assertEquals(7,backup.getInt("format"));assertFalse(backup.toString().contains("private-token"));Backup.restoreData(target.store,backup);RecordEntry r=Records.all(target.store).get(0);assertEquals("com.provider.sleep",HealthSleepCodec.read(r.healthConnect).origin);assertEquals(2,HealthSleepCodec.read(r.healthConnect).stages.size());assertTrue(target.store.rows("SELECT * FROM health_imports").isEmpty());assertTrue(target.store.rows("SELECT * FROM health_exports").isEmpty());assertEquals("",new HealthSleepStore(target.store).token());for(int version=1;version<=6;version++){JSONObject old=new JSONObject(backup.toString()).put("format",version);Backup.restoreData(target.store,old);assertEquals("",Records.all(target.store).get(0).healthConnect);}}}
 @Test public void malformedTypedSourceRejectsBeforeTargetReplacement()throws Exception{try(Fixture f=new Fixture();Fixture target=new Fixture()){f.local.apply(List.of(f.source("remote",1,"")),List.of(),"a","org.sleepwell.app",f.now);JSONObject valid=f.store.backup();String before=BackupFingerprint.read(target.store);for(String bad:List.of("fraction","string","origin","mismatch","oversized","duplicate")){JSONObject root=new JSONObject(valid.toString());JSONObject session=root.getJSONArray("sessions").getJSONObject(0);JSONObject metadata=new JSONObject(session.getString("health_connect"));switch(bad){case "fraction":metadata.put("modified",1.5);break;case "string":metadata.put("modified","1");break;case "origin":metadata.put("origin","not a package");break;case "mismatch":metadata.put("start",f.start+1);break;case "oversized":metadata.put("notes","x".repeat(20001));break;default:JSONObject second=new JSONObject(session.toString()).put("id",2);root.getJSONArray("sessions").put(second);root.getJSONArray("edits").put(new JSONObject(root.getJSONArray("edits").getJSONObject(0).toString()).put("session",2));}session.put("health_connect",metadata.toString());assertThrows(JSONException.class,()->Backup.restoreData(target.store,root));assertEquals(before,BackupFingerprint.read(target.store));}}}
 @Test public void exportIdentityVersionAcknowledgementAndRetirementAreDurable()throws Exception{try(Fixture f=new Fixture()){long id=Records.create(f.store,new RecordDraft(f.start,f.end),java.time.ZoneId.of("Europe/Berlin"),f.now);HealthSleepStore.Export first=f.local.prepare(Records.get(f.store,id),"org.sleepwell.app"),retry=f.local.prepare(Records.get(f.store,id),"org.sleepwell.app");assertEquals(first.client,retry.client);assertEquals(first.version,retry.version);assertTrue(f.local.ack(first,"provider-owned"));assertNull(f.local.prepare(Records.get(f.store,id),"org.sleepwell.app"));RecordEntry r=Records.get(f.store,id);RecordDraft draft=r.edit.copy();draft.note="Changed local note";Records.save(f.store,id,draft,r.updated,f.now+1);HealthSleepStore.Export changed=f.local.prepare(r,"org.sleepwell.app");assertEquals("Changed local note",changed.data.notes);assertEquals(first.client,changed.client);assertEquals(first.version+1,changed.version);Records.delete(f.store,id,Records.get(f.store,id).updated);assertEquals(List.of(first.client),f.local.retired());f.local.retiredDone(first.client);assertTrue(f.local.retired().isEmpty());}}
 @Test public void restoreAndEraseFencePendingSyncWithoutMutatingUnrelatedAlarms()throws Exception{try(Fixture f=new Fixture()){Alarm a=new Alarm(91);a.enabled=false;f.store.save(a);long id=Records.create(f.store,new RecordDraft(f.start,f.end),java.time.ZoneId.of("UTC"),f.now);HealthSleepStore.Export prepared=f.local.prepare(Records.get(f.store,id),"org.sleepwell.app");JSONObject saved=f.store.backup();Backup.restoreData(f.store,saved);assertThrows(IllegalStateException.class,()->f.local.admit(prepared));HealthSleepStore current=new HealthSleepStore(f.store);current.apply(List.of(f.source("remote",1,"Private")),List.of(),"a","org.sleepwell.app",f.now);f.store.eraseHistory();assertThrows(IllegalStateException.class,current::check);assertEquals("hidden",f.store.rows("SELECT status FROM health_imports").get(0).getString("status"));assertEquals("",f.store.rows("SELECT payload FROM health_imports").get(0).getString("payload"));assertNotNull(f.store.alarm(91));assertTrue(f.store.rows("SELECT * FROM sessions").isEmpty());}}
 @Test public void bothCsvPathsPreserveQuotedHistoricalSourceEvidence()throws Exception{try(Fixture f=new Fixture()){f.local.apply(List.of(f.source("remote",1,"Quoted, note \"safe\"")),List.of(),"a","org.sleepwell.app",f.now);assertEquals(Records.csv(f.store),new String(BackupDocuments.csv(f.store,()->true),java.nio.charset.StandardCharsets.UTF_8));assertTrue(Records.csv(f.store).startsWith("start_iso"));assertTrue(Records.csv(f.store).contains("health_connect\r\n"));}}
 @Test public void genuineNineToTenMigrationPreservesEveryOldTypedValue()throws Exception{String oldName="health-nine-"+UUID.randomUUID()+".db";try(SoundLabelFixture seedFixture=new SoundLabelFixture(c);Store seed=seedFixture.open()){Map<String,List<JSONObject>> original=new LinkedHashMap<>();Map<String,String> columns=new LinkedHashMap<>();for(String table:BackupFingerprint.TABLES){if(table.startsWith("health_"))continue;List<String> names=new ArrayList<>();for(JSONObject col:seed.rows("PRAGMA table_info("+table+")"))if(!col.getString("name").equals("health_connect"))names.add(col.getString("name"));String fields=String.join(",",names);columns.put(table,fields);original.put(table,seed.rows("SELECT "+fields+" FROM "+table+" ORDER BY rowid"));}List<JSONObject> schema=seed.rows("SELECT name,sql FROM sqlite_master WHERE sql IS NOT NULL AND name NOT LIKE 'sqlite_%' AND name!='android_metadata' ORDER BY CASE type WHEN 'table' THEN 0 WHEN 'index' THEN 1 ELSE 2 END,name");try(SQLiteDatabase db=SQLiteDatabase.openOrCreateDatabase(c.getDatabasePath(oldName),null)){for(JSONObject object:schema)if(!object.getString("name").startsWith("health_"))db.execSQL(object.getString("sql").replaceAll(",\\s*health_connect TEXT NOT NULL DEFAULT ''",""));db.execSQL("ATTACH DATABASE ? AS seed",new Object[]{c.getDatabasePath(seedFixture.database).getAbsolutePath()});for(String table:columns.keySet())db.execSQL("INSERT INTO "+table+"("+columns.get(table)+") SELECT "+columns.get(table)+" FROM seed."+table);db.execSQL("DETACH DATABASE seed");db.setVersion(9);}try(Store upgraded=new Store(c,oldName)){assertEquals(10,upgraded.getReadableDatabase().getVersion());for(String table:columns.keySet())assertEquals(table,original.get(table).toString(),upgraded.rows("SELECT "+columns.get(table)+" FROM "+table+" ORDER BY rowid").toString());assertEquals("",upgraded.rows("SELECT health_connect FROM sessions").get(0).getString("health_connect"));assertTrue(upgraded.rows("SELECT * FROM health_imports").isEmpty());assertTrue(upgraded.rows("SELECT * FROM health_exports").isEmpty());assertEquals("ok",upgraded.rows("PRAGMA integrity_check").get(0).getString("integrity_check"));assertTrue(seedFixture.file.exists());}}finally{c.deleteDatabase(oldName);}}
}
